import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const badge = new THREE.Group();
  badge.position.fromArray(config.scenePosition);
  badge.rotation.fromArray(config.sceneRotation);
  badge.scale.fromArray(config.sceneScale);

  // Load ceramic-grain texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  // Main badge plane with texture
  const geometry = new THREE.PlaneGeometry(0.4, 0.15);
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    color: new THREE.Color(config.colors.paper),
    transparent: true,
  });
  const mesh = new THREE.Mesh(geometry, material);
  badge.add(mesh);

  // Accent edge plane (behind main plane for depth)
  const edgeGeometry = new THREE.PlaneGeometry(0.42, 0.17);
  const edgeMaterial = new THREE.MeshBasicMaterial({
    color: new THREE.Color(config.colors.accent),
    transparent: true,
    opacity: 0.35,
  });
  const edgeMesh = new THREE.Mesh(edgeGeometry, edgeMaterial);
  edgeMesh.position.z = -0.001;
  badge.add(edgeMesh);

  const timelines = [];

  badge.userData.handlers = {
    onHover: () => {
      gsap.killTweensOf(badge.position);
      timelines.push(gsap.to(badge.position, {
        y: badge.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      }));
    },
    onHoverEnd: () => {
      gsap.killTweensOf(badge.position);
      timelines.push(gsap.to(badge.position, {
        y: config.scenePosition[1],
        duration: 0.5,
        ease: 'power2.out',
      }));
    },
    onClick: () => {
      gsap.killTweensOf(badge.scale);
      const tl = gsap.timeline();
      tl.to(badge.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      }, 0).to(badge.scale, {
        x: 1,
        y: 1,
        duration: 0.1,
        ease: 'back.out',
      });
      timelines.push(tl);

      const clickBehavior = config.behaviors?.find(b => b.event === 'click');
      if (clickBehavior) {
        const eventName = clickBehavior.effect.replace('emit:', '');
        ctx.emit?.(eventName);
      }
    },
  };

  badge.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    geometry.dispose();
    material.dispose();
    edgeGeometry.dispose();
    edgeMaterial.dispose();
  };

  return badge;
}
